<?php
require_once __DIR__.'/../includes/bootstrap.php';require_admin();
$title='Management Settings';$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();$action=(string)($_POST['action']??'');
 try{
  if($action==='store'){
   $phone=trim((string)$_POST['customer_care_phone']);$wa=preg_replace('/\D+/','',(string)$_POST['customer_care_whatsapp']);$support=trim((string)$_POST['support_email']);$tag=trim((string)$_POST['store_tagline']);$hours=max(1,min(168,(int)$_POST['cart_reminder_hours']));
   if($support!==''&&!filter_var($support,FILTER_VALIDATE_EMAIL))$err='Enter a valid support email.';else{foreach(['customer_care_phone'=>$phone,'customer_care_whatsapp'=>$wa,'support_email'=>$support,'store_tagline'=>$tag,'cart_reminder_hours'=>(string)$hours] as $k=>$v)$pdo->prepare('INSERT INTO store_config(config_key,config_value) VALUES(?,?) ON DUPLICATE KEY UPDATE config_value=VALUES(config_value)')->execute([$k,$v]);audit_log('UPDATE STORE SETTINGS','Customer care and communication settings');$msg='Store settings saved. Customer-facing contact controls now use the new values.';}
  }elseif($action==='social'){
   foreach(['facebook','twitter','linkedin','instagram','tiktok'] as $platform){$url=trim((string)($_POST[$platform]??''));if($url!==''&&!preg_match('#^https?://#i',$url))$err='Social links must begin with http:// or https://.';else{$pdo->prepare('INSERT INTO store_social_links(platform,url) VALUES(?,?) ON DUPLICATE KEY UPDATE url=VALUES(url)')->execute([$platform,$url]);}}
   if(!$err){audit_log('UPDATE SOCIAL LINKS','Store social destinations');$msg='Social links saved.';}
  }
 }catch(Throwable $e){$err='The settings could not be saved.';}
}
$get=function($k,$d=''){return store_config_value($k,$d);};$social=social_links();
