>Customer-care phone<input name="customer_care_phone" value="<?=e($get('customer_care_phone','+254707315280'))?>" required></label><label>WhatsApp number<input name="customer_care_whatsapp" value="<?=e($get('customer_care_whatsapp','254707315280'))?>" required><small class="muted">Use digits with country code, e.g. 254707315280.</small></label><label>Support email<input type="email" name="support_email" value="<?=e($get('support_email','otumas18@gmail.com'))?>"></label><label>Store tagline<input name="store_tagline" value="<?=e($get('store_tagline','Shop smart. Live better.'))?>"></label><label>Cart reminder after (hours)<input type="number" name="cart_reminder_hours" min="1" max="168" value="<?=e($get('cart_reminder_hours','24'))?>"></label><button class="btn primary">Save store controls</button></form></section><section class="panel"><h2>Social media</h2><p class="muted">These destinations appear in the lower footer. Leave a field empty to hide that platform.</p><form method="post" class="form"><?=csrf_field()?><input type="hidden" name="action" value="social"><label>Facebook<input name="facebook" value="<?=e($social['facebook']??'')?>" placeholder="https://facebook.com/..."></label><label>X / Twitter<input name="twitter" value="<?=e($social['twitter']??'')?>" placeholder="https://x.com/..."></label><label>LinkedIn<input name="linkedin" value="<?=e($social['linkedin']??'')?>" placeholder="https://linkedin.com/..."></label><label>Instagram<input name="instagram" value="<?=e($social['instagram']??'')?>" placeholder="https://instagram.com/..."></label><label>TikTok<input name="tiktok" value="<?=e($social['tiktok']??'')?>" placeholder="https://tiktok.com/@..."></label><button class="btn primary">Save social links</button></form></section></div></section></div><?php require __DIR__.'/../includes/footer.php';?>
